import base64,hashlib,io,json,zipfile,stat,os,shutil,subprocess,re,datetime
from pathlib import Path,PurePosixPath
carrier=""
expected=json.loads("[{\"path\":\"AI-DISCLOSURE.md\",\"mode\":\"100644\",\"bytes\":578,\"sha256\":\"f3a9b47aeee8b8f353632012d6816cbb9d24bddbf04358a8d2fc0921ce75796a\",\"git_blob\":\"a7c78b66d3d366a80108cb7650f894d293d70fa7\",\"origin\":\"unchanged qualified source\"},{\"path\":\"MANIFEST.sha256\",\"mode\":\"100644\",\"bytes\":616,\"sha256\":\"c0ef6bb1aa105024fa47800701e7a5409e8b3acda7a6ef66d789ff932735aea1\",\"git_blob\":\"654a200ea39ea1dc9f161ead8d9ed2d02ec2835c\",\"origin\":\"new delivery documentation\"},{\"path\":\"SOURCE-PROVENANCE.json\",\"mode\":\"100644\",\"bytes\":3224,\"sha256\":\"e8209402ceddb7f674daf2461942ea71c758cb6f4472be9889cebb5ba13b5aa4\",\"git_blob\":\"4243f30417e5fbe6d2142c8dc417790386db02bf\",\"origin\":\"new delivery documentation\"},{\"path\":\"START-HERE.html\",\"mode\":\"100644\",\"bytes\":3625,\"sha256\":\"be0548a518d3841ddc90351453f58bbb07a0702f7d2a01533ad4fd7e0738ed57\",\"git_blob\":\"9f2be3e41696f02c05b38166e08f7ceffb7d4302\",\"origin\":\"new delivery documentation\"},{\"path\":\"courses/edit-distance-explorer.html\",\"mode\":\"100644\",\"bytes\":47877,\"sha256\":\"eff706073ff25346d0b88e3f292ffcf02158db147f9f4dae0e18d1e08e2f3a01\",\"git_blob\":\"e358cedae9a3b7f14ecb2d341faa3417f75d0cff\",\"origin\":\"unchanged qualified source\"},{\"path\":\"courses/edit-distance.json\",\"mode\":\"100644\",\"bytes\":11066,\"sha256\":\"753499d3f6909d46d7628a5cabd85f2f5d2f94e9719d58313cbf13d73374df99\",\"git_blob\":\"df3aaf73eac33ce64ca7efd098a200385749a70e\",\"origin\":\"unchanged qualified source\"},{\"path\":\"courses/edit-distance.md\",\"mode\":\"100644\",\"bytes\":9713,\"sha256\":\"e48e2bbb2bad6f05cca0c64b8714d19f36b99de701555e019de283fb80a25a57\",\"git_blob\":\"249bd1dfc7b4156f6d4496465afc10439c6bca24\",\"origin\":\"unchanged qualified source\"},{\"path\":\"demo.html\",\"mode\":\"100644\",\"bytes\":98468,\"sha256\":\"fe7d44d125f9797c867251c05f02868a7cacf91c7d5129f46bbca3c69dc7ae1d\",\"git_blob\":\"ef7bc3e27e7f161d917ced6a457fad8822802f3f\",\"origin\":\"unchanged qualified source\"}]")
stage=Path("/Users/me/Developer/recallweave-edit-distance-local-c945953fdeb7")
target=Path("/Users/me/Applications/RecallWeaveEditDistance-c945953fdeb7")
assert not os.path.lexists(stage) and not os.path.lexists(target),"Exclusive proposed path is occupied"
disk=shutil.disk_usage(target.parent).free
v=subprocess.run(["/usr/bin/vm_stat"],capture_output=True,text=True,check=True,timeout=5).stdout
page=int(re.search(r"page size of (\d+) bytes",v).group(1))
memory=sum(int(re.search(r"^"+re.escape(k)+r":\s+(\d+)",v,re.M).group(1)) for k in ["Pages free","Pages inactive","Pages speculative"])*page
assert disk>=256*1024*1024 and memory>=2*1024**3,(disk,memory)
def pin(data):
    return {"bytes":len(data),"sha256":hashlib.sha256(data).hexdigest(),"git_blob":hashlib.sha1(b"blob "+str(len(data)).encode()+b"\0"+data).hexdigest()}
assert len(carrier)==71380 and hashlib.sha256(carrier.encode("ascii")).hexdigest()=="48a772124737ebe5ff2eab773e6e6b10da2675619bbff0c05173f8598a0667fa"
data=base64.b64decode(carrier,validate=True)
assert pin(data)=={"bytes":53535,"sha256":"a86d823d70be98d08fd804ce9d8bccdb071b586adf5c30c0784a96a5db2a03e9","git_blob":"ae0f3ed4e067fd527b1db7e103270419242db0c2"}
with zipfile.ZipFile(io.BytesIO(data)) as z:
    infos=z.infolist()
    names=[i.filename for i in infos]
    assert len(names)==len(set(names))==8 and set(names)==set(x["path"] for x in expected)
    values={}
    observed=[]
    for x in expected:
        p=PurePosixPath(x["path"]);assert not p.is_absolute() and ".." not in p.parts
        i=z.getinfo(x["path"]);assert not i.is_dir() and not i.flag_bits&1 and stat.S_IFMT(i.external_attr>>16)==stat.S_IFREG
        assert format(i.external_attr>>16,"o")==x["mode"]
        body=z.read(i)
        assert pin(body)=={k:x[k] for k in ["bytes","sha256","git_blob"]}
        values[x["path"]]=body
        observed.append({"path":x["path"],"mode":x["mode"],**pin(body)})
    checks={}
    for line in values["MANIFEST.sha256"].decode("ascii").splitlines():
        digest,name=line.split(None,1)
        assert name not in checks and name!="MANIFEST.sha256"
        assert hashlib.sha256(values[name]).hexdigest()==digest
        checks[name]=digest
    assert set(checks)==set(names)-{"MANIFEST.sha256"}
    deck=json.loads(values["courses/edit-distance.json"])
    assert len(deck["items"])==12
print(json.dumps({"schema":"recall.edit-distance.original-only-memory-admission.v2","utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"device":"Mac.lan","free_disk":disk,"conservative_memory":memory,"stage":str(stage),"target":str(target),"both_exclusive_paths_absent":True,"carrier":pin(carrier.encode("ascii")),"original_zip":pin(data),"members":observed,"seven_original_manifest_entries_exact":True,"course_title":deck.get("title"),"question_count":len(deck["items"]),"native_files_written":0,"product_or_builder_invocations":0,"network_requests":0,"admission_observer_correction":"V1 stopped after exact ZIP/member checks because the observer looked for questions instead of the original deck items field; no files or product were executed. V1 is preserved unchanged.","reader_dependency":"Original demo ef7bc3e remains exact. Qualified strict UTF-8 replacement belongs to #7/#181 and #109/#159 integration owners; excluded from this installation."},separators=(",",":")))
